describe('validatePluginName', () => {
  const PREFIX = 'modern-errors-';

  it('should throw TypeError when plugin is null', () => {
    expect(() => validatePluginName(null)).toThrow(TypeError);
  });

  it('should throw TypeError when plugin is undefined', () => {
    expect(() => validatePluginName(undefined)).toThrow(TypeError);
  });

  it('should throw TypeError when plugin is not an object', () => {
    expect(() => validatePluginName('string')).toThrow(TypeError);
    expect(() => validatePluginName(123)).toThrow(TypeError);
    expect(() => validatePluginName(true)).toThrow(TypeError);
  });

  it('should throw TypeError when name property is missing', () => {
    const plugin = { version: '1.0.0' };
    expect(() => validatePluginName(plugin)).toThrow(TypeError);
  });

  it('should throw TypeError when name property is not a string', () => {
    const plugin = { name: 123 };
    expect(() => validatePluginName(plugin)).toThrow(TypeError);

    const plugin2 = { name: {} };
    expect(() => validatePluginName(plugin2)).toThrow(TypeError);

    const plugin3 = { name: null };
    expect(() => validatePluginName(plugin3)).toThrow(TypeError);
  });

  it('should return new object with fullName property when name is valid', () => {
    const plugin = { name: 'testplugin', version: '1.0.0' };
    const result = validatePluginName(plugin);

    expect(result).toEqual({
      name: 'testplugin',
      version: '1.0.0',
      fullName: PREFIX + 'testplugin'
    });
  });

  it('should not modify the original plugin object', () => {
    const plugin = { name: 'testplugin', version: '1.0.0' };
    const originalPlugin = { ...plugin };

    validatePluginName(plugin);

    expect(plugin).toEqual(originalPlugin);
    expect(plugin).not.toHaveProperty('fullName');
  });

  it('should handle valid names with digits', () => {
    const plugin = { name: 'testplugin123' };
    const result = validatePluginName(plugin);

    expect(result).toEqual({
      name: 'testplugin123',
      fullName: PREFIX + 'testplugin123'
    });
  });

  it('should return new object instance', () => {
    const plugin = { name: 'testplugin' };
    const result = validatePluginName(plugin);

    expect(result).not.toBe(plugin);
    expect(typeof result).toBe('object');
  });

  it('should throw TypeError when name contains uppercase letters', () => {
    const plugin = { name: 'TestPlugin' };
    expect(() => validatePluginName(plugin)).toThrow(TypeError);
  });

  it('should throw TypeError when name contains special characters', () => {
    const plugin = { name: 'test-plugin' };
    expect(() => validatePluginName(plugin)).toThrow(TypeError);

    const plugin2 = { name: 'test_plugin' };
    expect(() => validatePluginName(plugin2)).toThrow(TypeError);
  });

  it('should throw TypeError when name is empty string', () => {
    const plugin = { name: '' };
    expect(() => validatePluginName(plugin)).toThrow(TypeError);
  });
