describe('addInstanceMethod', () => {
  let TestError;
  let plugin;
  let plugins;

  beforeEach(() => {
    // Create a test error class
    TestError = class extends Error {
      constructor(message) {
        super(message);
        this.name = 'TestError';
      }
    };

    // Mock plugin objects
    plugin = { name: 'testPlugin' };
    plugins = [{ name: 'plugin1' }, { name: 'plugin2' }];
  });

  it('should add a non-enumerable instance method to the ErrorClass prototype', () => {
    const methodName = 'customMethod';
    const methodFunc = jest.fn(function() {
      return `Hello from ${this.name}`;
    });

    addInstanceMethod(plugin, plugins, TestError, methodName, methodFunc);

    // Check that the method exists on the prototype
    expect(TestError.prototype[methodName]).toBeDefined();
    expect(typeof TestError.prototype[methodName]).toBe('function');

    // Check that the method is non-enumerable
    const descriptor = Object.getOwnPropertyDescriptor(TestError.prototype, methodName);
    expect(descriptor.enumerable).toBe(false);

    // Check that the method works correctly
    const instance = new TestError('test message');
    const result = instance[methodName]();
    expect(result).toBe('Hello from TestError');
    expect(methodFunc).toHaveBeenCalled();
  });

  it('should add a non-enumerable static method to the ErrorClass', () => {
    const methodName = 'staticMethod';
    const methodFunc = jest.fn(function() {
      return 'Static method called';
    });

    addInstanceMethod(plugin, plugins, TestError, methodName, methodFunc);

    // Check that the static method exists on the class
    expect(TestError[methodName]).toBeDefined();
    expect(typeof TestError[methodName]).toBe('function');

    // Check that the method is non-enumerable
    const descriptor = Object.getOwnPropertyDescriptor(TestError, methodName);
    expect(descriptor.enumerable).toBe(false);

    // Check that the static method works correctly
    const result = TestError[methodName]();
    expect(result).toBe('Static method called');
    expect(methodFunc).toHaveBeenCalled();
  });

  it('should bind the instance method to the current instance', () => {
    const methodName = 'boundMethod';
    const methodFunc = jest.fn(function() {
      return this;
    });

    addInstanceMethod(plugin, plugins, TestError, methodName, methodFunc);

    const instance = new TestError('test message');
    const result = instance[methodName]();

    // The method should be bound to the instance
    expect(result).toBe(instance);
    expect(methodFunc).toHaveBeenCalled();
  });

  it('should throw TypeError if ErrorClass is not a function', () => {
    const methodName = 'testMethod';
    const methodFunc = function() {};

    expect(() => {
      addInstanceMethod(plugin, plugins, {}, methodName, methodFunc);
    }).toThrow(TypeError);

    expect(() => {
      addInstanceMethod(plugin, plugins, null, methodName, methodFunc);
    }).toThrow(TypeError);

    expect(() => {
      addInstanceMethod(plugin, plugins, undefined, methodName, methodFunc);
    }).toThrow(TypeError);
  });

  it('should throw TypeError if methodName is not a string', () => {
    const methodFunc = function() {};

    expect(() => {
      addInstanceMethod(plugin, plugins, TestError, 123, methodFunc);
    }).toThrow(TypeError);

    expect(() => {
      addInstanceMethod(plugin, plugins, TestError, null, methodFunc);
    }).toThrow(TypeError);

    expect(() => {
      addInstanceMethod(plugin, plugins, TestError, undefined, methodFunc);
    }).toThrow(TypeError);
  });

