  class AnotherError extends Error {}

  test('should return empty object when classOpts is undefined', () => {
    const result = normalizeClassOpts(ParentError);
    expect(result).toEqual({});
  });

  test('should return empty object when classOpts is explicitly an empty object', () => {
    const result = normalizeClassOpts(ParentError, {});
    expect(result).toEqual({});
  });

  test('should return the same object when classOpts is a plain object', () => {
    const opts = { key: 'value', number: 42 };
    const result = normalizeClassOpts(ParentError, opts);
    expect(result).toBe(opts);
  });

  test('should throw TypeError when classOpts is null', () => {
    expect(() => {
      normalizeClassOpts(ParentError, null);
    }).toThrow(TypeError);
  });

  test('should throw TypeError with descriptive message when classOpts is null', () => {
    expect(() => {
      normalizeClassOpts(ParentError, null);
    }).toThrow(`The second argument of "ParentError.subclass()" must be a plain object, not: null`);
  });

  test('should throw TypeError when classOpts is an array', () => {
    expect(() => {
      normalizeClassOpts(ParentError, []);
    }).toThrow(TypeError);
  });

  test('should throw TypeError with descriptive message when classOpts is an array', () => {
    expect(() => {
      normalizeClassOpts(ParentError, []);
    }).toThrow(`The second argument of "ParentError.subclass()" must be a plain object, not: `);
  });

  test('should throw TypeError when classOpts is a string', () => {
    expect(() => {
      normalizeClassOpts(ParentError, 'string');
    }).toThrow(TypeError);
  });

  test('should throw TypeError when classOpts is a number', () => {
    expect(() => {
      normalizeClassOpts(ParentError, 42);
    }).toThrow(TypeError);
  });

  test('should throw TypeError when classOpts is a boolean', () => {
    expect(() => {
      normalizeClassOpts(ParentError, true);
    }).toThrow(TypeError);
  });

  test('should throw TypeError when classOpts is a function', () => {
    expect(() => {
      normalizeClassOpts(ParentError, () => {});
    }).toThrow(TypeError);
  });

  test('should throw TypeError when classOpts is a Date object', () => {
    expect(() => {
      normalizeClassOpts(ParentError, new Date());
    }).toThrow(TypeError);
  });

  test('should include correct parent error class name in error message', () => {
    expect(() => {
      normalizeClassOpts(AnotherError, 'invalid');
    }).toThrow(`The second argument of "AnotherError.subclass()" must be a plain object, not: invalid`);
  });

  test('should work with different parent error classes', () => {
