const shouldPrefixCause = require('../../../src/merge/prefix').shouldPrefixCause;

describe('shouldPrefixCause', () => {
  test('returns false when error is null', () => {
    expect(shouldPrefixCause(null, Error)).toBe(false);
  });

  test('returns false when error is undefined', () => {
    expect(shouldPrefixCause(undefined, Error)).toBe(false);
  });

  test('returns false when error is not an object', () => {
    expect(shouldPrefixCause('not an object', Error)).toBe(false);
    expect(shouldPrefixCause(42, Error)).toBe(false);
    expect(shouldPrefixCause(true, Error)).toBe(false);
  });

  test('returns false when error has no cause property', () => {
    const error = new Error('test error');
    expect(shouldPrefixCause(error, Error)).toBe(false);
  });

  test('returns false when cause is null', () => {
    const error = { cause: null };
    expect(shouldPrefixCause(error, Error)).toBe(false);
  });

  test('returns false when cause is undefined', () => {
    const error = { cause: undefined };
    expect(shouldPrefixCause(error, Error)).toBe(false);
  });

  test('returns false when cause has no name property', () => {
    const error = { cause: {} };
    expect(shouldPrefixCause(error, Error)).toBe(false);
  });

  test('returns false when cause.name is empty string', () => {
    const error = { cause: { name: '' } };
    expect(shouldPrefixCause(error, Error)).toBe(false);
  });

  test('returns false when cause.name is only whitespace', () => {
    const error = { cause: { name: '   ' } };
    expect(shouldPrefixCause(error, Error)).toBe(false);
  });

  test('returns false when ErrorClass is not a function', () => {
    const error = { cause: { name: 'TestError' } };
    expect(shouldPrefixCause(error, 'not a function')).toBe(false);
    expect(shouldPrefixCause(error, null)).toBe(false);
    expect(shouldPrefixCause(error, undefined)).toBe(false);
    expect(shouldPrefixCause(error, {})).toBe(false);
  });

  test('returns true when cause name matches ErrorClass name and is useful', () => {
    const error = { cause: { name: 'ReferenceError' } };
    expect(shouldPrefixCause(error, ReferenceError)).toBe(true);
  });

