const mergePrefixedError = require('../../../src/merge/cause');
const { prefixCause } = require('../../../src/merge/cause/prefixCause');
const { mergeErrorCause } = require('../../../src/merge/cause/mergeErrorCause');
const { undoPrefixing } = require('../../../src/merge/cause/undoPrefixing');

describe('mergePrefixedError', () => {
  beforeEach(() => {
    jest.clearAllMocks();
  });

  it('should merge prefixed error successfully', () => {
    // Override mock implementation for this specific test
    mergeErrorCause.mockImplementation((cause) => {
      if (cause === null || cause === undefined) return cause;
      return {
        ...cause,
        message: `Merged: ${cause.message}`
      };
    });

    const originalCause = { message: 'Original error' };
    const error = { cause: originalCause };

    const result = mergePrefixedError(error);

    expect(prefixCause).toHaveBeenCalledWith(originalCause);
    expect(mergeErrorCause).toHaveBeenCalledWith({
      ...originalCause,
      message: 'Prefixed: Original error'
    });
    expect(result.message).toBe('Merged: Prefixed: Original error');

    // Reset mock implementation
    mergeErrorCause.mockImplementation((cause) => {
      if (cause === null || cause === undefined) return cause;
      if (cause.message === 'Prefixed: Original error') {
        return {
          ...cause,
          message: 'Different merged cause'
        };
      }
      return cause;
    });
  });

  it('should undo prefixing when merged cause differs from original cause', () => {
    const originalCause = { message: 'Original error' };
    const error = { cause: originalCause };

    const result = mergePrefixedError(error);

    expect(prefixCause).toHaveBeenCalledWith(originalCause);
    expect(mergeErrorCause).toHaveBeenCalledWith({
      ...originalCause,
      message: 'Prefixed: Original error'
    });
    expect(undoPrefixing).toHaveBeenCalledWith({
      ...originalCause,
      message: 'Different merged cause'
    });
    expect(result.message).toBe('Undone: Different merged cause');
  });

  it('should throw TypeError when error is null', () => {
    expect(() => mergePrefixedError(null)).toThrow(TypeError);
  });

