const { deepCloneObject } = require('../../../src/options/clone.js');

describe('deepCloneObject', () => {
  test('should create a deep clone of a simple object', () => {
    const original = { a: 1, b: 2 };
    const cloned = deepCloneObject(original);

    expect(cloned).toEqual(original);
    expect(cloned).not.toBe(original);
  });

  test('should create a deep clone of nested objects', () => {
    const original = {
      a: 1,
      b: {
        c: 2,
        d: {
          e: 3
        }
      }
    };
    const cloned = deepCloneObject(original);

    expect(cloned).toEqual(original);
    expect(cloned).not.toBe(original);
    expect(cloned.b).not.toBe(original.b);
    expect(cloned.b.d).not.toBe(original.b.d);
  });

  test('should preserve property descriptors', () => {
    const original = {};
    Object.defineProperty(original, 'nonEnumerable', {
      value: 'hidden',
      enumerable: false,
      writable: true,
      configurable: true
    });
    Object.defineProperty(original, 'readOnly', {
      value: 'readonly',
      enumerable: true,
      writable: false,
      configurable: false
    });

    const cloned = deepCloneObject(original);

    expect(cloned.nonEnumerable).toBe('hidden');
    expect(cloned.readOnly).toBe('readonly');

    const nonEnumerableDescriptor = Object.getOwnPropertyDescriptor(cloned, 'nonEnumerable');
    const readOnlyDescriptor = Object.getOwnPropertyDescriptor(cloned, 'readOnly');

    expect(nonEnumerableDescriptor.enumerable).toBe(false);
    expect(nonEnumerableDescriptor.writable).toBe(true);
    expect(nonEnumerableDescriptor.configurable).toBe(true);

    expect(readOnlyDescriptor.enumerable).toBe(true);
    expect(readOnlyDescriptor.writable).toBe(false);
    expect(readOnlyDescriptor.configurable).toBe(false);
  });

  test('should handle arrays correctly', () => {
    const original = {
      arr: [1, 2, { nested: 'value' }],
      nested: {
        arr2: [3, 4]
      }
    };
    const cloned = deepCloneObject(original);

    expect(cloned).toEqual(original);
    expect(cloned.arr).not.toBe(original.arr);
    expect(cloned.arr[2]).not.toBe(original.arr[2]);
    expect(cloned.nested.arr2).not.toBe(original.nested.arr2);
  });

  test('should handle null values', () => {
    const original = {
      a: null,
      b: {
        c: null
      }
    };
    const cloned = deepCloneObject(original);

    expect(cloned).toEqual(original);
    expect(cloned.b).not.toBe(original.b);
  });

  test('should handle mixed data types', () => {
    const original = {
      str: 'string',
      num: 42,
      bool: true,
      undef: undefined,
      n: null,
      obj: {
        nested: 'value'
      }
    };
    const cloned = deepCloneObject(original);

    expect(cloned).toEqual(original);
    expect(cloned.obj).not.toBe(original.obj);
  });

  test('should throw TypeError for non-object input', () => {
    expect(() => deepCloneObject(null)).toThrow(TypeError);
    expect(() => deepCloneObject(undefined)).toThrow(TypeError);
    expect(() => deepCloneObject('string')).toThrow(TypeError);
    expect(() => deepCloneObject(42)).toThrow(TypeError);
    expect(() => deepCloneObject(true)).toThrow(TypeError);
  });

  test('should handle objects with symbol keys', () => {
    const sym = Symbol('test');
    const original = {
      a: 1,
      [sym]: 'symbol value'
    };
    original[sym] = 'symbol value';

    const cloned = deepCloneObject(original);

    expect(cloned).toEqual(original);
    expect(cloned).not.toBe(original);
    expect(cloned[sym]).toBe('symbol value');
  });

  test('should preserve original object unchanged', () => {
    const original = {
      a: 1,
      b: {
        c: 2
      }
    };
    const originalSnapshot = JSON.parse(JSON.stringify(original));

    deepCloneObject(original);

    expect(original).toEqual(originalSnapshot);
    expect(original.b).toEqual(originalSnapshot.b);
  });

  test('should handle empty objects', () => {
    const original = {};
    const cloned = deepCloneObject(original);

    expect(cloned).toEqual({});
    expect(cloned).not.toBe(original);
  });

  test('should handle objects with inherited properties', () => {
    const Parent = function() {
      this.parentProp = 'parent';
    };
    Parent.prototype.inheritedProp = 'inherited';

    const original = new Parent();
    original.ownProp = 'own';

    const cloned = deepCloneObject(original);

    expect(cloned.ownProp).toBe('own');
    expect(cloned.parentProp).toBe('parent');
    // Inherited properties are not own properties, so they won't be cloned
    expect(cloned.inheritedProp).toBeUndefined();
  });
});

