    const original = [1, [2, 3], [4, [5, 6]]];
    const cloned = deepClone(original);

    expect(cloned).toEqual(original);
    expect(cloned).not.toBe(original);
    expect(cloned[1]).not.toBe(original[1]); // Nested array should be different reference
    expect(cloned[2]).not.toBe(original[2]);
    expect(cloned[2][1]).not.toBe(original[2][1]); // Deeply nested array should be different reference
  });

  test('should clone plain objects with primitive values', () => {
    const original = { a: 1, b: 'test', c: true, d: null };
    const cloned = deepClone(original);

    expect(cloned).toEqual(original);
    expect(cloned).not.toBe(original); // Should be different references
  });

